import {getState,update,setAutonomy,decide,canReviewDecision} from './store.js';
import {esc,icon,badge,avatar,progress,money,empty} from './ui.js';
export const personas=[['transformation','Transformation','h-matthieu','Toute l’organisation'],['executive','Direction générale','h-matthieu','Objectifs, valeur et transformation'],['security','Sécurité & conformité','h-sophie','Politiques, événements et accès'],['finance','Finance','h-claire','Coûts, budgets et valeur'],['people','Responsable des équipes','h-matthieu','Registre et développement'],['manager','Manager de groupe','h-julien','Distribution et délégations'],['team','Manager d’équipe','h-claire','Opérations et processus'],['member','Collaborateur','h-lea','Son travail et ses agents'],['admin','Administrateur','h-matthieu','Rôles, modèles et connecteurs']];
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
const copy=x=>JSON.parse(JSON.stringify(x));
export const permissionLabels={read:'Lire et rechercher',draft:'Travailler dans son espace',send:'Envoyer et publier',initiative:'Prendre des initiatives',delete:'Supprimer ou remplacer',production:'Modifier la production',access:'Changer les accès',spend:'Engager une dépense',legal:'Accepter des conditions',computer:'Utiliser un ordinateur'};
const initialPermissions={read:'allow',draft:'allow',send:'ask',initiative:'ask',delete:'ask',production:'never',access:'never',spend:'ask',legal:'never',computer:'ask'};
const record=value=>value&&typeof value==='object'&&!Array.isArray(value)?value:{};
export function initializeWorkspace(s){
 const defaults={version:2,mode:'teams',personaId:'transformation',actorId:'h-matthieu',selectedAgentId:'a-quill',agentTab:'chat',showDetails:false,watchScreen:false,selectedGroupId:null,agentHoursLimit:720};
 s.workspace={...defaults,...record(s.workspace)};
 const w=s.workspace;w.version=Math.max(Number(w.version)||0,2);w.agentConfig=record(w.agentConfig);w.threads=record(w.threads);
 for(const key of ['proposals','tasks','knowledge','notifications'])if(!Array.isArray(w[key]))w[key]=[];
 if(!Array.isArray(w.groups))w.groups=[{id:'grp-close',name:'Clôture & contrôles',members:['a-atlas','a-sentinel','a-nova'].filter(id=>s.agents.some(a=>a.id===id)),messages:[]}];
 for(const group of w.groups){if(!Array.isArray(group.messages))group.messages=[];if(!Array.isArray(group.members))group.members=[];}
 if(!s.agents.some(a=>a.id===w.selectedAgentId&&a.type==='agent'))w.selectedAgentId=s.agents.find(a=>a.type==='agent')?.id||null;
 if(!s.agents.some(a=>a.id===w.actorId&&a.type==='human'))w.actorId=s.agents.find(a=>a.type==='human')?.id||null;
 if(!personas.some(p=>p[0]===w.personaId))w.personaId='transformation';
 if(!['chat','overview','setup'].includes(w.agentTab))w.agentTab='chat';
 if(w.selectedGroupId&&!w.groups.some(g=>g.id===w.selectedGroupId&&g.members.some(id=>s.agents.some(a=>a.id===id&&a.type==='agent'))))w.selectedGroupId=null;
 for(const a of s.agents.filter(a=>a.type==='agent')){
  const base={permissions:{...initialPermissions},hourLimit:160,spendLimit:150,rules:['Citer les sources utilisées.','Présenter les incertitudes au responsable.'],sites:['documents.northstar.example','crm.northstar.example'],model:'Routage supervisé',strategy:'Sources approuvées en premier',strategyVersion:2,apps:(a.mandate?.tools||[]).map(name=>({name,read:true,write:false,connected:true})),memories:[{id:'memory-initial-'+a.id,text:'Les données de cet espace sont fictives. Aucun envoi réel.',source:'Règle de l’espace'}],changes:[],reports:[{id:'today',label:'Aujourd’hui',title:'Le travail avance, un arbitrage reste attendu.',body:'Les dossiers ont été préparés à partir des sources autorisées. Les actions externes attendent une décision humaine.'},{id:'week',label:'Cette semaine',title:'Qualité, charge et points d’attention',body:'Le scénario de démonstration présente les résultats acceptés, les reprises et les exceptions. Ces chiffres ne proviennent pas d’une organisation réelle.'}],experiment:{status:'running',current:91,challenger:94,currentCases:42,challengerCases:38,target:100}};
  const previous=record(w.agentConfig[a.id]),cfg={...base,...previous,permissions:{...initialPermissions,...record(previous.permissions)},experiment:{...base.experiment,...record(previous.experiment)}};
  for(const key of ['rules','sites','apps','memories','changes','reports'])if(!Array.isArray(cfg[key]))cfg[key]=base[key];
  w.agentConfig[a.id]=cfg;
  if(!Array.isArray(w.threads[a.id]))w.threads[a.id]=[{id:uid('msg'),role:'agent',text:`Je suis ${a.name}. ${a.mandate?.mission||a.role} Mes propositions restent dans cet espace jusqu’à votre validation.`,time:'2026-11-04T08:00:00Z',trace:['Lire le mandat et les sources autorisées','Préparer le résultat et ses justificatifs','Appliquer les contrôles avant toute action'],artifact:a.id==='a-quill'?{name:'Réponse Horizon — brouillon.txt',text:'Objet : Proposition Horizon\n\nLe dossier comporte 18 réponses approuvées et 2 engagements de service à confirmer. Merci de valider ces engagements avant diffusion.',type:'email',to:'contact@horizon.example',subject:'Proposition Horizon — pour revue'}:null}];
 }
 if(!w.seeded){w.seeded=true;const append=(items,records)=>records.forEach(r=>{if(!items.some(x=>x.id===r.id))items.push(r)});append(w.knowledge,[{id:'doc-policy',name:'Guide de gouvernance Northstar.txt',content:'Toute action sensible est attribuée à un responsable. Les résultats doivent citer leurs sources. Les communications externes sont revues avant diffusion.',agentIds:['a-quill','a-atlas','a-sentinel'],version:1,owner:'Matthieu Keip',status:'approved',updatedAt:'2026-11-04'}, {id:'doc-rfp',name:'Engagements commerciaux approuvés.txt',content:'Les engagements nouveaux et les conditions non standard doivent être validés par le responsable distribution.',agentIds:['a-quill'],version:1,owner:'Julien Moreau',status:'approved',updatedAt:'2026-11-04'}]);append(w.proposals,[{id:'prop-quill',agentId:'a-quill',title:'Vérifier les engagements avant la rédaction',from:2,to:3,reason:'Trois dossiers du scénario ont nécessité une reprise tardive.',change:'Ajouter un contrôle des engagements au début de la préparation.',before:86,after:93,cases:52,status:'pending',tested:false}]);append(w.tasks,[{id:'task-atlas',agentId:'a-atlas',title:'Préparer le rapprochement du matin',schedule:'Chaque jour ouvré à 08:30',status:'scheduled',due:'2026-11-05',result:''},{id:'task-quill',agentId:'a-quill',title:'Finaliser le dossier Horizon',schedule:'Après validation humaine',status:'waiting',due:'2026-11-04',result:''}]);}
 w.sessionId||=uid('workspace');
 for(const d of s.decisions.filter(d=>d.status==='pending'&&!d.assignedTo)){const agent=s.agents.find(a=>a.id===d.agentId),owner=s.processes.find(p=>p.id===d.processId)?.owner||agent?.mandate?.reviewer||agent?.manager;d.assignedTo=s.agents.find(a=>a.type==='human'&&(a.name===owner||a.id===owner))?.name||s.agents.find(a=>a.id===w.actorId)?.name;}
 return s;
}
export function initWorkspace(){const s=getState(),next={...s,workspace:copy(s.workspace||{}),decisions:copy(s.decisions)};initializeWorkspace(next);if(JSON.stringify(next.workspace)!==JSON.stringify(s.workspace)||JSON.stringify(next.decisions)!==JSON.stringify(s.decisions))update(st=>{st.workspace=next.workspace;st.decisions=next.decisions;},s.workspace?'Espace de travail synchronisé':'Espace étendu initialisé','Navigation, conversations et interventions locales');return getState().workspace;}
export function currentPersona(s){return personas.find(p=>p[0]===s.workspace?.personaId)||personas[0]}
export function agentAttention(s,id){const d=s.decisions.find(d=>d.agentId===id&&d.status==='pending');if(d)return {label:d.title,id:d.id,kind:'decision'};const p=s.workspace?.proposals.find(p=>p.agentId===id&&p.status==='pending');return p?{label:p.title,id:p.id,kind:'proposal'}:null;}
export function selectAgent(id,ctx){if(!ctx.getState().agents.some(a=>a.id===id&&a.type==='agent'))return;update(s=>{initializeWorkspace(s);s.workspace.selectedAgentId=id;s.workspace.selectedGroupId=null;s.workspace.agentTab='chat';s.workspace.mode='agents'},'Agent consulté',id);ctx.navigate('workbench');}
const btn=(action,label,id='',cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" data-id="${esc(id)}" ${extra}>${label}</button>`;
const options=(items,value)=>items.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('');
function proposalCard(p){return `<article class="ws-proposal"><div class="row between"><span class="eyebrow">AMÉLIORATION PROPOSÉE</span>${badge(p.status==='pending'?'Votre avis est attendu':p.status==='approved'?'Approuvée':'Conservée',p.status==='pending'?'amber':'green')}</div><h3>${esc(p.title)}</h3><p>${esc(p.change)}</p><p class="small muted">${esc(p.reason)} Version ${p.from} → ${p.to}. Cas de test fictifs : ${p.before}% → ${p.after}% sur ${p.cases} cas.</p>${p.tested?'<p class="positive small">Test local effectué ; résultat illustratif disponible dans le journal.</p>':''}${p.status==='pending'?`<div class="row">${btn('ws-proposal-test','Tester d’abord',p.id)}${btn('ws-proposal-approve','Approuver',p.id,'btn-primary')}${btn('ws-proposal-keep','Garder la version actuelle',p.id)}</div>`:''}</article>`;}
function interventionCard(d,s){const a=s.agents.find(a=>a.id===d.agentId);return `<article class="ws-intervention"><div class="row between"><span class="eyebrow">${icon('shield',13)} ${esc(a?.name||'Agent')} DEMANDE VOTRE ACCORD</span>${badge(d.priority==='high'?'Prioritaire':'À examiner','amber')}</div><h3>${esc(d.title)}</h3><p>${esc(d.summary)}</p><dl class="detail-grid"><div><dt>Processus</dt><dd>${esc(s.processes.find(p=>p.id===d.processId)?.name||'Travail individuel')}</dd></div><div><dt>Responsable</dt><dd>${esc(d.assignedTo||'Matthieu Keip')}</dd></div><div><dt>Échéance</dt><dd>${new Date(d.dueAt||d.createdAt).toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</dd></div><div><dt>Montant maximum</dt><dd>${money(d.amount||0)}</dd></div></dl><details><summary>Voir la demande et ses preuves</summary><ul>${(d.evidence||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>${esc(d.recommendation)}</p><p class="small muted">Accord limité à cette demande, à cet agent et à la version courante du mandat.</p></details><div class="row">${btn('ws-decision','Autoriser une fois',d.id,'btn-primary','data-outcome="approve"')}${btn('ws-decision','Refuser',d.id,'btn-danger','data-outcome="reject"')}${btn('ws-request-change','Demander une modification',d.id)}${btn('ws-reassign','Réaffecter',d.id)}</div>${d.revisionRequest?`<p class="small">Modification demandée : ${esc(d.revisionRequest)}</p>`:''}</article>`}
function artifactCard(m){const a=m.artifact;if(!a)return '';return `<section class="ws-artifact"><strong>${icon('edit',15)} ${esc(a.name)}</strong>${a.reviewStatus?badge(a.reviewStatus==='approved'?'Revue approuvée':a.reviewStatus==='rejected'?'Revue refusée':'Brouillon modifié',a.reviewStatus==='approved'?'green':'neutral'):''}${a.type==='email'?`<div class="field"><label>Destinataire fictif<input id="artifact-to-${esc(m.id)}" value="${esc(a.to)}"></label></div><div class="field"><label>Objet<input id="artifact-subject-${esc(m.id)}" value="${esc(a.subject)}"></label></div><div class="field"><label>Contenu<textarea id="artifact-body-${esc(m.id)}">${esc(a.text)}</textarea></label></div><div class="row">${btn('ws-save-artifact','Enregistrer le brouillon',m.id)}${btn('ws-submit-artifact','Soumettre à validation',m.id,'btn-primary')}</div>`:`<pre>${esc(a.text)}</pre>`}<div class="row">${btn('ws-download-artifact','Télécharger',m.id)}${btn('ws-discard-artifact','Retirer le brouillon',m.id)}</div></section>`;}
function chatView(a,s){const w=s.workspace,group=w.groups.find(g=>g.id===w.selectedGroupId);const messages=group?group.messages:w.threads[a.id]||[];return `<div class="ws-chat-layout ${w.showDetails?'has-details':''}"><section class="ws-conversation"><div class="ws-messages">${group?`<div class="notice">${icon('users',18)}<p>Groupe local de ${group.members.map(id=>esc(s.agents.find(x=>x.id===id)?.name||id)).join(', ')}. Les contributions et transferts sont simulés.</p></div>`:''}${messages.map(m=>`<article class="ws-message ${m.role==='user'?'from-user':''}"><div class="ws-message-meta">${m.role==='user'?avatar(s.agents.find(x=>x.id===w.actorId)||{name:'Vous',type:'human'}):avatar(a)}<strong>${m.role==='user'?'Vous':esc(m.agentName||a.name)}</strong><time>${new Date(m.time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}</time></div>${m.trace?`<details class="ws-trace"><summary>${icon('check',14)} Travail préparé · ${m.trace.length} étapes simulées</summary><ol>${m.trace.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><p>Stratégie : ${esc(w.agentConfig[a.id]?.strategy)}. Sources : documents autorisés de démonstration.</p></details>`:''}<p class="ws-message-text">${esc(m.text)}</p>${artifactCard(m)}${m.attachment?`<span class="tag">${icon('plug',13)} ${esc(m.attachment.name)}</span>`:''}</article>`).join('')}${!group?s.decisions.filter(d=>d.agentId===a.id&&d.status==='pending').map(d=>interventionCard(d,s)).join(''):''}${!group?w.proposals.filter(p=>p.agentId===a.id&&p.status==='pending').map(proposalCard).join(''):''}${w.watchScreen?`<section class="ws-screen"><div class="row between"><strong>Écran de travail · reconstitution locale</strong>${badge('Lecture seule','neutral')}</div><div class="ws-screen-browser">documents.northstar.example / espace approuvé</div><h3>Pièces réunies pour la revue</h3>${w.knowledge.filter(d=>d.status==='approved'&&d.agentIds.includes(a.id)).map(d=>`<p>${icon('check',14)} ${esc(d.name)} · v${d.version}</p>`).join('')||'<p>Aucune pièce rattachée.</p>'}<p class="small muted">Cette vue représente les traces du scénario. Aucun navigateur distant n’est piloté.</p></section>`:''}</div><div class="ws-composer"><div class="ws-prompts">${['Que dois-je valider ?','Prépare une synthèse sourcée','Propose une amélioration'].map(p=>`<button class="tag" data-action="ws-prompt" data-value="${esc(p)}">${esc(p)}</button>`).join('')}</div><div class="ws-input-row"><button class="icon-button" data-action="ws-attach" aria-label="Joindre un fichier texte">${icon('plus')}</button><textarea id="ws-message" rows="2" placeholder="Donnez une responsabilité, demandez un résultat…" aria-label="Message à l’agent"></textarea><button class="btn btn-primary" data-action="ws-send" aria-label="Envoyer le message">${icon('send',17)}</button></div><input id="ws-file" type="file" accept=".txt,.csv,.md,.json" hidden><small>Réponses de démonstration · aucune action externe. ${btn('ws-tab','Voir ce qu’il peut faire','setup','btn-ghost btn-sm')}</small></div></section>${w.showDetails?detailsPanel(a,s):''}</div>`;}
function detailsPanel(a,s){const w=s.workspace;return `<aside class="ws-context"><h3>Contexte de ${esc(a.name)}</h3><div class="small muted">Rattaché à ${esc(a.manager)}</div><h4>À faire</h4>${w.tasks.filter(t=>t.agentId===a.id).map(t=>`<div class="ws-context-item"><strong>${esc(t.title)}</strong><small>${esc(t.schedule)} · ${esc(t.status)}</small>${btn('ws-task-detail','Ouvrir',t.id,'btn-sm')}</div>`).join('')}${btn('ws-new-task','Ajouter une tâche',a.id,'btn-sm')}<h4>Documents & résultats</h4>${w.knowledge.filter(d=>d.agentIds.includes(a.id)).map(d=>btn('ws-doc-detail',esc(d.name),d.id,'ws-file-link')).join('')}${btn('ws-new-doc','Ajouter un document',a.id,'btn-sm')}<h4>Contexte retenu</h4>${w.agentConfig[a.id].memories.map(m=>`<div class="ws-memory"><p>${esc(m.text)}</p><small>${esc(m.source)}</small>${btn('ws-remove-memory',icon('x',12),m.id,'icon-button','aria-label="Supprimer ce souvenir"')}</div>`).join('')}${btn('ws-add-memory','Ajouter une note',a.id,'btn-sm')}<h4>Activité récente</h4>${s.audit.filter(e=>(e.detail||'').includes(a.id)||(e.detail||'').includes(a.name)).slice(0,5).map(e=>`<p class="small">${esc(e.action)}<small class="muted"> ${new Date(e.time).toLocaleTimeString('fr-FR')}</small></p>`).join('')||'<p class="small muted">Aucune modification récente.</p>'}</aside>`;}
function overviewAgent(a,s){const w=s.workspace,c=w.agentConfig[a.id],goal=s.goals.find(g=>g.id===a.objectiveId);return `<div class="ws-agent-overview"><div class="ws-hero"><div>${avatar(a,'lg')}<h2>${esc(a.name)}</h2><p>${esc(a.mandate?.mission||a.role)}</p></div><div><strong>${a.hours} h</strong><small>travaillées dans le scénario ce mois-ci</small></div></div><div class="stat-grid"><div class="stat-card"><div class="stat-label">Qualité vérifiée</div><div class="stat-value">${a.quality}%</div><small>Scénario de démonstration</small></div><div class="stat-card"><div class="stat-label">Interventions attendues</div><div class="stat-value">${s.decisions.filter(d=>d.agentId===a.id&&d.status==='pending').length}</div><small>Avant toute action sensible</small></div><div class="stat-card"><div class="stat-label">Coût simulé</div><div class="stat-value">${money(a.cost)}</div><small>Novembre 2026</small></div><div class="stat-card"><div class="stat-label">Stratégie en usage</div><div class="stat-value">v${c.strategyVersion}</div><small>${esc(c.strategy)}</small></div></div>${w.proposals.filter(p=>p.agentId===a.id).map(proposalCard).join('')}<section class="card pad"><div class="row between"><h3>Objectif et résultats clés</h3>${btn('gov-new-goal','Définir un objectif',a.id)}</div>${goal?`<h2>${esc(goal.title)}</h2>${progress(goal.progress)}<div class="detail-grid">${goal.krs.map(k=>`<div><strong>${esc(k.label)}</strong><p>${k.current}${esc(k.unit)} / ${k.target}${esc(k.unit)}</p></div>`).join('')}</div>${btn('gov-goal-detail','Tracer la progression',goal.id)}`:empty('Pas encore d’objectif','Rattachez cet agent à un résultat attendu.')}</section><section class="card pad"><div class="row between"><h3>Comment il travaille</h3>${badge('Expérience fictive','neutral')}</div><h4>${esc(c.strategy)} · v${c.strategyVersion}</h4><p>Commencer par les sources validées, comparer les éléments concordants, signaler les divergences, puis produire une proposition vérifiable.</p><details><summary>Pourquoi cette méthode ?</summary><p>Le scénario compare la qualité acceptée, le temps de revue et les résultats des cas de test. Une hausse apparente ne suffit pas à prouver un gain en production.</p></details><div class="ws-experiment"><div class="row between"><strong>Essai comparatif d’une stratégie</strong>${badge(c.experiment.status==='running'?'En cours':c.experiment.status==='promoted'?'Challenger adopté':'Arrêté','purple')}</div><div class="grid-2"><div><h4>Version actuelle</h4><strong>${c.experiment.current}%</strong><p>${c.experiment.currentCases} cas fictifs</p></div><div><h4>Contrôle des sources renforcé</h4><strong>${c.experiment.challenger}%</strong><p>${c.experiment.challengerCases} cas fictifs</p></div></div><p class="small muted">Seuil de revue : ${c.experiment.target} cas par variante. Aucune significativité statistique revendiquée.</p>${c.experiment.status==='running'?`<div class="row">${btn('ws-experiment','Adopter le challenger',a.id,'','data-value="promoted"')}${btn('ws-experiment','Arrêter le test',a.id,'','data-value="stopped"')}</div>`:''}</div>${btn('ws-new-proposal','Proposer une évolution de méthode',a.id)}</section><section class="card pad"><h3>Compétences</h3><div class="tag-list">${a.skills.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>${btn('nav','Ouvrir l’université','','','data-value="skills"')}</section><section class="card pad"><h3>Rapports spontanés</h3><div class="ws-tabs">${c.reports.map(r=>btn('ws-report',esc(r.label),r.id)).join('')}</div><h4>${esc(c.reports.find(r=>r.id===(w.reportId||'today'))?.title||c.reports[0]?.title||'Aucun rapport disponible')}</h4><p>${esc(c.reports.find(r=>r.id===(w.reportId||'today'))?.body||c.reports[0]?.body||'Les prochains rapports apparaîtront ici.')}</p></section><section class="card pad"><h3>Décisions et versions</h3>${c.changes.length?c.changes.slice().reverse().map(ch=>`<div class="ws-context-item"><strong>${esc(ch.title)}</strong><small>${esc(ch.date)} · ${esc(ch.evidence)}</small>${!ch.reverted?btn('ws-revert-change','Revenir à la version précédente',ch.id,'btn-sm'):badge('Annulée','neutral')}</div>`).join(''):'<p class="muted">Les changements approuvés apparaîtront ici avec leurs preuves.</p>'}</section></div>`;}
function setupAgent(a,s){const c=s.workspace.agentConfig[a.id];return `<div class="ws-setup"><div class="notice">${icon('shield',18)}<p>Les règles de l’organisation et le mandat restent prioritaires. Ces réglages illustrent le contrôle local du démonstrateur.</p></div><section class="card pad"><div class="row between"><h3>Autonomie</h3>${btn('org-edit-mandate','Modifier le mandat complet',a.id)}</div><div class="ws-autonomy">${[['Observateur','Lit et rend compte.'],['Assistant','Prépare, puis demande avant d’agir.'],['Opérateur','Agit dans un mandat explicite.'],['Autonome','Exceptions et limites restent humaines.']].map(([l,d],i)=>`<button class="${a.autonomy===i?'selected':''}" data-action="ws-autonomy" data-value="${i}"><strong>${l}</strong><small>${d}</small></button>`).join('')}</div></section><section class="card pad"><h3>Permissions de ${esc(a.name)}</h3><p class="small muted">Un accord permanent concerne seulement cette catégorie d’action et cet agent. Les limites de dépense, l’accès et les conditions légales restent encadrés.</p>${Object.entries(permissionLabels).map(([k,label])=>`<div class="ws-permission"><div><strong>${label}</strong>${['spend','legal','access','production'].includes(k)?'<small>Plafond de l’organisation</small>':''}</div><div class="ws-segments">${[['allow','Autoriser'],['ask','Demander'],['never','Jamais']].map(([v,l])=>`<button class="${c.permissions[k]===v?'active':''}" data-action="ws-permission" data-key="${k}" data-value="${v}" ${v==='allow'&&['spend','legal','access','production'].includes(k)?'disabled title="Validation du responsable obligatoire"':''}>${l}</button>`).join('')}</div></div>`).join('')}</section><section class="card pad"><div class="row between"><h3>Applications et accès</h3>${btn('nav','Catalogue de connexions','','','data-value="integrations"')}</div>${c.apps.map((app,i)=>`<div class="ws-app-row"><div><strong>${esc(app.name)}</strong><small>${app.connected?'Accès simulé actif':'Déconnecté localement'}</small></div><div class="row">${btn('ws-app',app.read?'Lecture autorisée':'Lecture bloquée',String(i),'btn-sm','data-value="read"')}${btn('ws-app',app.write?'Écriture autorisée':'Écriture bloquée',String(i),'btn-sm','data-value="write"')}${btn('ws-app',app.connected?'Déconnecter':'Reconnecter',String(i),'btn-sm','data-value="connected"')}</div></div>`).join('')}</section><section class="card pad"><div class="row between"><h3>Heures et dépenses</h3>${btn('ws-limits','Ajuster les limites',a.id)}</div><p>${a.hours} h sur ${c.hourLimit} h maximum dans le mois</p>${progress(a.hours/c.hourLimit*100)}<p>Maximum par action : ${money(c.spendLimit)}. Toute dépense nécessite une validation.</p></section><section class="card pad"><div class="row between"><h3>Règles propres à l’agent</h3>${btn('ws-add-rule','Ajouter une règle',a.id)}</div>${c.rules.map((r,i)=>`<div class="ws-rule"><span>${esc(r)}</span>${btn('ws-remove-rule',icon('x',13),String(i),'icon-button','aria-label="Retirer la règle"')}</div>`).join('')}<p class="small muted">Les consignes rédigées sont déclaratives. Les permissions structurées déterminent les contrôles locaux.</p></section><section class="card pad"><div class="row between"><h3>Sites autorisés</h3>${btn('ws-add-site','Ajouter un domaine',a.id)}</div>${c.sites.map((r,i)=>`<div class="ws-rule"><code>${esc(r)}</code>${btn('ws-remove-site',icon('x',13),String(i),'icon-button','aria-label="Retirer le domaine"')}</div>`).join('')}<p class="small muted">Liste illustrative ; aucun navigateur autonome n’est connecté.</p></section><section class="card pad"><div class="row between"><h3>Activité de l’agent</h3>${btn('org-toggle-agent',a.status==='paused'?'Réactiver':'Suspendre',a.id)}</div><p>La suspension bloque les nouvelles simulations jusqu’à réactivation.</p></section></div>`;}
export function renderWorkbench(s){const w=s.workspace,a=s.agents.find(a=>a.id===w.selectedAgentId&&a.type==='agent')||s.agents.find(a=>a.type==='agent');if(!a)return empty('Créez votre premier agent','Ouvrez le catalogue ou décrivez sa responsabilité.');const group=w.groups.find(g=>g.id===w.selectedGroupId);return `<header class="ws-workbench-head"><div class="row">${avatar(a,'lg')}<div><h1>${esc(group?.name||a.name)}</h1><p>${esc(group?'Groupe de travail':agentAttention(s,a.id)?'Votre intervention est attendue':a.status==='paused'?'Suspendu':a.role)} · ${esc(a.manager)}</p></div></div><div class="row"><div class="ws-tabs">${[['chat','Conversation'],['overview','Vue d’ensemble'],['setup','Réglages']].map(([k,l])=>btn('ws-tab',l,k,w.agentTab===k?'btn-primary':'')).join('')}</div>${w.agentTab==='chat'?`<button class="icon-button ${w.watchScreen?'selected':''}" data-action="ws-watch" title="Voir l’écran simulé" aria-label="Voir l’écran simulé">${icon('grid',18)}</button><button class="icon-button ${w.showDetails?'selected':''}" data-action="ws-details" title="Afficher tâches, fichiers et contexte" aria-label="Afficher les détails">${icon('inbox',18)}</button>`:''}</div></header>${w.agentTab==='setup'?setupAgent(a,s):w.agentTab==='overview'?overviewAgent(a,s):chatView(a,s)}`;}
export function renderInterventions(s,workflowItems=[]){const open=s.decisions.filter(d=>d.status==='pending');return `<header class="page-head"><div><div class="eyebrow">LE JUGEMENT RESTE HUMAIN</div><h1 class="page-title">Ce qui a besoin de vous.</h1><p class="page-description">Chaque demande garde son agent, son contexte, ses preuves et son responsable.</p></div>${badge((open.length+workflowItems.length)+' interventions','amber')}</header><div class="ws-intervention-grid">${workflowItems.map(d=>`<article class="ws-intervention"><div class="row between">${badge('Workflow en attente','amber')}<span class="small muted">${esc(d.owner||'Responsable')}</span></div><h3>${esc(d.title)}</h3><p>${esc(d.detail)}</p>${btn('ws-open-run','Examiner l’étape et décider',d.id,'btn-primary')}</article>`).join('')}${open.map(d=>interventionCard(d,s)).join('')}${!open.length&&!workflowItems.length?empty('Aucune demande en attente','Les prochaines exceptions apparaîtront ici et dans le panneau gauche.'):''}</div><section class="card pad"><h3>Arbitrages terminés</h3>${s.decisions.filter(d=>d.status!=='pending').map(d=>`<div class="ws-context-item"><strong>${esc(d.title)}</strong><small>${esc(d.status)} · ${esc(d.comment||d.revisionRequest||'Décision consignée')}</small>${btn('gov-decision-detail','Consulter la trace',d.id,'btn-sm')}</div>`).join('')||'<p class="muted small">Aucun arbitrage dans cette session.</p>'}</section>`;}
export function renderKnowledge(s){const docs=s.workspace.knowledge;return `<header class="page-head"><div><div class="eyebrow">CONTEXTE PARTAGÉ</div><h1 class="page-title">Des sources que l’on peut vérifier.</h1><p class="page-description">Documents, versions, responsables et agents autorisés.</p></div>${btn('ws-new-doc','Ajouter un document','','btn-primary')}</header><div class="grid-3">${docs.map(d=>`<article class="card pad"><div class="row between">${icon('inbox')}${badge(d.status==='approved'?'Approuvé':'Brouillon',d.status==='approved'?'green':'neutral')}</div><h3>${esc(d.name)}</h3><p class="small muted">Version ${d.version} · ${esc(d.owner)}</p><p>${esc(d.content.slice(0,150))}…</p><div class="tag-list">${d.agentIds.map(id=>`<span class="tag">${esc(s.agents.find(a=>a.id===id)?.name||id)}</span>`).join('')}</div><div class="row">${btn('ws-doc-detail','Lire et modifier',d.id)}${btn('ws-doc-download','Télécharger',d.id)}</div></article>`).join('')}</div>`;}
const download=(name,text)=>{const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
export function handleWorkspace(action,el,ctx){if(!action.startsWith('ws-'))return false;const s=getState(),w=s.workspace,a=s.agents.find(x=>x.id===w.selectedAgentId)||s.agents.find(x=>x.type==='agent'),c=w.agentConfig[a?.id],ident=el.dataset.id,value=el.dataset.value;
 const mutate=(fn,title,detail=a?.name||'')=>update(fn,title,detail),editOne=(title,label,current,save,type='textarea')=>ctx.modal({title,body:`<div class="field"><label for="ws-edit">${esc(label)}</label>${type==='input'?`<input id="ws-edit" name="value" value="${esc(current)}" required maxlength="500">`:`<textarea id="ws-edit" name="value" required maxlength="10000">${esc(current)}</textarea>`}</div>`,onSubmit:fd=>save(String(fd.get('value')).trim())});
 if(action==='ws-mode'){mutate(st=>st.workspace.mode=value,'Espace sélectionné',value);ctx.navigate(value==='agents'?'workbench':value==='teams'?'organization':'overview');return true;}
 if(action==='ws-select-agent'){selectAgent(ident,ctx);return true;}
 if(action==='ws-tab'){mutate(st=>st.workspace.agentTab=ident,'Vue agent',ident);return true;}
 if(action==='ws-details'||action==='ws-watch'){mutate(st=>st.workspace[action==='ws-details'?'showDetails':'watchScreen']=!st.workspace[action==='ws-details'?'showDetails':'watchScreen'],'Vue de travail',a.name);return true;}
 if(action==='ws-persona'){ctx.modal({title:'Explorer un rôle',subtitle:'Changement de point de vue dans la démonstration ; aucune authentification réelle.',body:`<div class="field"><label for="ws-persona">Rôle</label><select id="ws-persona" name="persona">${options(personas.map(p=>[p[0],p[1]+' — '+p[3]]),w.personaId)}</select></div><div class="field"><label for="ws-actor">Responsable qui agit</label><select id="ws-actor" name="actor">${options(s.agents.filter(x=>x.type==='human').map(x=>[x.id,x.name+' — '+x.role]),w.actorId)}</select></div>`,onSubmit:fd=>{mutate(st=>{st.workspace.personaId=fd.get('persona');st.workspace.actorId=fd.get('actor');},'Point de vue changé',fd.get('persona'));ctx.navigate(['member','team'].includes(fd.get('persona'))?'organization':fd.get('persona')==='security'?'security':fd.get('persona')==='admin'?'administration':fd.get('persona')==='finance'?'spend':fd.get('persona')==='people'?'workforce':'overview')}});return true;}
 if(action==='ws-prompt'){document.getElementById('ws-message').value=value;document.getElementById('ws-message').focus();return true;}
 if(action==='ws-send'){const text=document.getElementById('ws-message')?.value.trim();if(!text)return true;if(a.status==='paused'){ctx.toast('Réactivez l’agent avant de lancer un travail.');return true;}mutate(st=>{const ww=st.workspace,group=ww.groups.find(g=>g.id===ww.selectedGroupId),list=group?group.messages:ww.threads[a.id];list.push({id:uid('msg'),role:'user',text,time:new Date().toISOString()});const needs=st.decisions.filter(d=>d.agentId===a.id&&d.status==='pending');const response=/valid|interven|attend/i.test(text)?(needs.length?`J’attends votre décision sur ${needs.map(d=>d.title).join(' ; ')}. Vous pouvez consulter les preuves, réaffecter ou demander une modification.`:'Aucune décision ne bloque mon travail actuellement.'):/amélior|strateg|méthode/i.test(text)?'Je propose de comparer la méthode actuelle à un contrôle des sources renforcé. Ouvrez ma vue d’ensemble pour examiner les cas et décider de la version.':`Voici une proposition de travail pour « ${text.slice(0,180)} » : réunir les sources approuvées, vérifier le mandat, préparer un résultat sourcé puis vous soumettre les écarts. Cette réponse est issue du scénario local, sans appel à un modèle.`;list.push({id:uid('msg'),role:'agent',agentName:group?st.agents.find(x=>x.id===group.members[0])?.name:a.name,text:response,time:new Date().toISOString(),trace:['Consulter la demande et le mandat','Retrouver les documents approuvés','Proposer un résultat à revoir'],artifact:/synthèse|rapport|brief|rédig/i.test(text)?{name:'Synthèse de démonstration.txt',text:`Demande : ${text}\n\nSources : ${ww.knowledge.filter(d=>d.status==='approved'&&d.agentIds.includes(a.id)).map(d=>d.name).join(', ')}\n\nProposition : préparer le livrable, signaler les incertitudes et obtenir la validation du responsable. Aucun système externe contacté.`,type:'text'}:null});},'Message et réponse simulée',a.name);return true;}
 if(action==='ws-decision'){const d=s.decisions.find(d=>d.id===ident);if(!d||d.status!=='pending')return true;ctx.modal({title:el.dataset.outcome==='approve'?'Autoriser cette demande une seule fois':'Refuser cette demande',subtitle:d.title,body:`<div class="field"><label for="ws-decision-comment">Motif de la décision</label><textarea id="ws-decision-comment" name="comment" required></textarea></div><p class="small muted">Responsable actuel : ${esc(s.agents.find(x=>x.id===w.actorId)?.name)}. Le responsable désigné ou un supérieur hiérarchique peut arbitrer. L’auteur réel reste tracé.</p>`,submitLabel:el.dataset.outcome==='approve'?'Autoriser une fois':'Refuser',onSubmit:fd=>{const r=decide(ident,el.dataset.outcome,String(fd.get('comment')),{actorId:getState().workspace.actorId});ctx.toast(r.ok?'Décision enregistrée ; la revue est tracée.':r.error);return r.ok;}});return true;}
 if(action==='ws-reassign'){const d=s.decisions.find(x=>x.id===ident);if(!d||d.status!=='pending')return true;if(!canReviewDecision(s,d,w.actorId)){ctx.toast('Seul le responsable ou son supérieur peut réaffecter cette demande.');return true;}ctx.modal({title:'Réaffecter l’intervention',body:`<div class="field"><label for="ws-reviewer">Responsable</label><select id="ws-reviewer" name="reviewer">${options(s.agents.filter(x=>x.type==='human'&&x.status!=='paused').map(x=>[x.name,x.name]),d.assignedTo)}</select></div>`,onSubmit:fd=>{const current=getState(),request=current.decisions.find(d=>d.id===ident),owner=current.agents.find(a=>a.type==='human'&&a.status!=='paused'&&a.name===fd.get('reviewer'));if(request?.status!=='pending'||!canReviewDecision(current,request,current.workspace.actorId)||!owner){ctx.toast('La demande ou les responsabilités ont changé. Réexaminez l’intervention.');return false;}return mutate(st=>st.decisions.find(x=>x.id===ident).assignedTo=owner.name,'Intervention réaffectée',d.title);}});return true;}
 if(action==='ws-request-change'){const request=s.decisions.find(d=>d.id===ident);if(request?.status!=='pending'||!canReviewDecision(s,request,w.actorId)){ctx.toast('Seul le responsable ou son supérieur peut demander une reprise.');return true;}editOne('Demander une modification','Précisez ce qui doit être repris','',text=>{const current=getState(),d=current.decisions.find(d=>d.id===ident);if(!text||d?.status!=='pending'||!canReviewDecision(current,d,current.workspace.actorId)){ctx.toast('La demande doit être en attente et relever de votre responsabilité.');return false;}return mutate(st=>{const d=st.decisions.find(x=>x.id===ident);d.revisionRequest=text;d.evidence||=[];d.evidence.push('Reprise demandée : '+text);st.workspace.threads[d.agentId]||=[];st.workspace.threads[d.agentId].push({id:uid('msg'),role:'user',text:'Modification demandée : '+text,time:new Date().toISOString()});},'Reprise demandée',ident);});return true;}
 if(['ws-proposal-test','ws-proposal-approve','ws-proposal-keep'].includes(action)){const p=w.proposals.find(p=>p.id===ident);if(!p||p.status!=='pending')return true;const owner=s.agents.find(a=>a.id===p.agentId)?.manager;if(action!=='ws-proposal-test'&&!canReviewDecision(s,{assignedTo:owner},w.actorId)){ctx.toast('Le responsable de cet agent ou son supérieur doit arbitrer la proposition.');return true;}if(action==='ws-proposal-approve'&&w.agentConfig[p.agentId]?.strategyVersion!==p.from){ctx.toast('La stratégie a changé depuis cette proposition. Préparez une proposition sur la version actuelle.');return true;}if(action==='ws-proposal-test'){mutate(st=>st.workspace.proposals.find(x=>x.id===ident).tested=true,'Évaluation locale de proposition',p.title);ctx.toast('52 cas fictifs comparés. Aucune preuve de performance réelle.');return true;}if(action==='ws-proposal-approve'&&!p.tested){ctx.toast('Testez la proposition avant de la promouvoir.');return true;}mutate(st=>{const pp=st.workspace.proposals.find(x=>x.id===ident);pp.status=action==='ws-proposal-approve'?'approved':'kept';if(pp.status==='approved'){const cfg=st.workspace.agentConfig[pp.agentId];cfg.changes.push({id:uid('change'),title:pp.title,date:new Date().toLocaleDateString('fr-FR'),evidence:`Test local sur ${pp.cases} cas fictifs`,before:cfg.strategyVersion,after:pp.to});cfg.strategyVersion=pp.to;}},'Proposition arbitrée',p.title);return true;}
 if(action==='ws-new-proposal'){editOne('Proposer une évolution','Nouvelle méthode à tester','',text=>mutate(st=>st.workspace.proposals.push({id:uid('prop'),agentId:a.id,title:text.slice(0,90),change:text,reason:'Proposition humaine à éprouver sur des cas de démonstration.',from:c.strategyVersion,to:c.strategyVersion+1,before:a.quality,after:a.quality,cases:52,status:'pending',tested:false}),'Évolution proposée'));return true;}
 if(action==='ws-experiment'){ctx.modal({title:value==='promoted'?'Adopter la méthode challenger':'Arrêter cet essai',subtitle:'Décision humaine sur un essai illustratif. Les seuils ne sont pas encore atteints.',body:'<div class="field"><label for="exp-reason">Justification</label><textarea id="exp-reason" name="reason" required></textarea></div>',onSubmit:fd=>mutate(st=>{const cfg=st.workspace.agentConfig[a.id];cfg.experiment.status=value;cfg.changes.push({id:uid('change'),title:value==='promoted'?'Challenger adopté':'Essai arrêté',date:new Date().toLocaleDateString('fr-FR'),evidence:fd.get('reason'),before:cfg.strategyVersion,after:cfg.strategyVersion+(value==='promoted'?1:0)});if(value==='promoted')cfg.strategyVersion++;},'Essai arbitré')});return true;}
 if(action==='ws-revert-change'){const ch=c.changes.find(x=>x.id===ident);if(!ch||ch.reverted)return true;if(c.strategyVersion!==ch.after){ctx.toast('Une version ultérieure existe. Annulez d’abord le dernier changement.');return true;}mutate(st=>{const cfg=st.workspace.agentConfig[a.id];cfg.strategyVersion=ch.before;cfg.changes.find(x=>x.id===ident).reverted=true;},'Version précédente rétablie');return true;}
 if(action==='ws-report'){mutate(st=>st.workspace.reportId=ident,'Rapport consulté');return true;}
 if(action==='ws-autonomy'){const r=setAutonomy(a.id,Number(value));ctx.toast(r.ok?'Autonomie mise à jour.':r.error);return true;}
 if(action==='ws-permission'){const key=el.dataset.key;if(!Object.hasOwn(permissionLabels,key)||!['allow','ask','never'].includes(value))return true;if(value==='allow'&&['spend','legal','access','production'].includes(key))return true;mutate(st=>st.workspace.agentConfig[a.id].permissions[key]=value,'Permission locale ajustée',a.name+' · '+key+' : '+value);return true;}
 if(action==='ws-app'){const i=Number(ident);if(c.apps[i]&&['read','write','connected'].includes(value))mutate(st=>st.workspace.agentConfig[a.id].apps[i][value]=!st.workspace.agentConfig[a.id].apps[i][value],'Accès applicatif simulé modifié');return true;}
 if(action==='ws-limits'){ctx.modal({title:'Heures et dépenses',body:`<div class="form-grid"><label class="field">Heures maximum par mois<input name="hours" type="number" min="1" max="10000" value="${c.hourLimit}" required></label><label class="field">Maximum par action (€)<input name="spend" type="number" min="0" max="100000" value="${c.spendLimit}" required></label></div>`,onSubmit:fd=>mutate(st=>{const cfg=st.workspace.agentConfig[a.id];cfg.hourLimit=Number(fd.get('hours'));cfg.spendLimit=Number(fd.get('spend'));},'Limites locales ajustées')});return true;}
 if(action==='ws-add-rule'||action==='ws-add-site'||action==='ws-add-memory'){editOne(action==='ws-add-site'?'Domaine autorisé':action==='ws-add-rule'?'Règle de l’agent':'Contexte à retenir',action==='ws-add-site'?'Nom de domaine sans protocole':'Contenu','',text=>{if(action==='ws-add-site'&&!/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(text)){ctx.toast('Saisissez un nom de domaine valide.');return false;}mutate(st=>{const cfg=st.workspace.agentConfig[a.id];if(action==='ws-add-site')cfg.sites.push(text);else if(action==='ws-add-rule')cfg.rules.push(text);else cfg.memories.push({id:uid('memory'),text,source:'Note humaine'});},'Contexte ajouté');},action==='ws-add-site'?'input':'textarea');return true;}
 if(action==='ws-remove-rule'||action==='ws-remove-site'||action==='ws-remove-memory'){mutate(st=>{const cfg=st.workspace.agentConfig[a.id];if(action==='ws-remove-rule')cfg.rules.splice(Number(ident),1);else if(action==='ws-remove-site')cfg.sites.splice(Number(ident),1);else cfg.memories=cfg.memories.filter(x=>x.id!==ident);},'Contexte retiré');return true;}
 if(action==='ws-new-group'){ctx.modal({title:'Créer un groupe de travail',body:`<label class="field">Nom du groupe<input name="name" required maxlength="80"></label><div class="field"><label>Membres</label>${s.agents.filter(x=>x.type==='agent').map(x=>`<label class="ws-check"><input type="checkbox" name="member" value="${esc(x.id)}"> ${esc(x.name)}</label>`).join('')}</div>`,onSubmit:fd=>{const members=fd.getAll('member');if(members.length<2){ctx.toast('Choisissez au moins deux agents.');return false;}const id=uid('group');mutate(st=>{st.workspace.groups.push({id,name:fd.get('name'),members,messages:[]});st.workspace.selectedGroupId=id;st.workspace.selectedAgentId=members[0];st.workspace.agentTab='chat';st.workspace.mode='agents';},'Groupe créé',fd.get('name'));ctx.navigate('workbench')}});return true;}
 if(action==='ws-group'){const g=w.groups.find(x=>x.id===ident);if(g){mutate(st=>{st.workspace.selectedGroupId=g.id;st.workspace.selectedAgentId=g.members[0];st.workspace.agentTab='chat';st.workspace.mode='agents';},'Groupe consulté',g.name);ctx.navigate('workbench');}return true;}
 if(action==='ws-new-task'||action==='ws-task-detail'){const t=w.tasks.find(x=>x.id===ident);ctx.modal({title:t?'Tâche & déclencheur':'Déléguer une tâche',subtitle:'Les récurrences sont enregistrées dans le scénario ; aucun ordonnanceur externe ne s’exécute.',body:`<label class="field">Responsabilité<input name="title" value="${esc(t?.title||'')}" required></label><label class="field">Agent<select name="agent">${options(s.agents.filter(x=>x.type==='agent').map(x=>[x.id,x.name]),t?.agentId||a.id)}</select></label><label class="field">Déclencheur / cadence<input name="schedule" value="${esc(t?.schedule||'À la demande')}" required></label><label class="field">Échéance<input type="date" name="due" value="${t?.due||'2026-11-05'}" required></label><label class="field">État<select name="status">${options([['scheduled','Planifiée'],['waiting','Attend une décision'],['completed','Terminée dans le scénario']],t?.status||'scheduled')}</select></label><label class="field">Résultat / preuve<textarea name="result">${esc(t?.result||'')}</textarea></label>`,onSubmit:fd=>{if(fd.get('status')==='completed'&&!String(fd.get('result')).trim()){ctx.toast('Ajoutez la preuve du résultat avant de terminer.');return false;}mutate(st=>{const entry={id:t?.id||uid('task'),title:fd.get('title'),agentId:fd.get('agent'),schedule:fd.get('schedule'),due:fd.get('due'),status:fd.get('status'),result:fd.get('result')};if(t)st.workspace.tasks[st.workspace.tasks.findIndex(x=>x.id===t.id)]=entry;else st.workspace.tasks.push(entry);},'Tâche enregistrée');}});return true;}
 if(action==='ws-new-doc'||action==='ws-doc-detail'){const d=w.knowledge.find(x=>x.id===ident);ctx.modal({title:d?'Document et autorisations':'Ajouter une source',body:`<label class="field">Nom<input name="name" value="${esc(d?.name||'')}" required></label><label class="field">Contenu texte<textarea name="content" required maxlength="60000">${esc(d?.content||'')}</textarea></label><label class="field">Responsable<input name="owner" value="${esc(d?.owner||s.agents.find(x=>x.id===w.actorId)?.name)}" required></label><label class="field">État<select name="status">${options([['draft','Brouillon'],['approved','Approuvé']],d?.status||'draft')}</select></label><div class="field"><label>Agents autorisés</label>${s.agents.filter(x=>x.type==='agent').map(x=>`<label class="ws-check"><input type="checkbox" name="agent" value="${x.id}" ${(d?.agentIds||[a?.id]).includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div>`,onSubmit:fd=>mutate(st=>{const doc={id:d?.id||uid('doc'),name:fd.get('name'),content:fd.get('content'),owner:fd.get('owner'),status:fd.get('status'),version:(d?.version||0)+1,agentIds:fd.getAll('agent'),updatedAt:new Date().toISOString()};if(d)st.workspace.knowledge[st.workspace.knowledge.findIndex(x=>x.id===d.id)]=doc;else st.workspace.knowledge.push(doc);},'Source enregistrée')});return true;}
 if(action==='ws-doc-download'){const d=w.knowledge.find(x=>x.id===ident);if(d)download(d.name,d.content);return true;}
 if(action==='ws-attach'){document.getElementById('ws-file')?.click();return true;}
 if(['ws-download-artifact','ws-discard-artifact','ws-save-artifact','ws-submit-artifact'].includes(action)){
  const group=w.groups.find(g=>g.id===w.selectedGroupId),messages=group?group.messages:w.threads[a?.id]||[],m=messages.find(x=>x.id===ident);
  if(!m?.artifact)return true;
  const findMessage=st=>(group?st.workspace.groups.find(g=>g.id===group.id)?.messages:st.workspace.threads[a.id])?.find(x=>x.id===ident);
  const cancelPending=(st,reason)=>{for(const d of st.decisions.filter(d=>d.artifactId===ident&&d.status==='pending')){d.status='cancelled';d.comment=reason;d.cancelledAt=new Date().toISOString();d.cancelledBy=st.agents.find(x=>x.id===st.workspace.actorId)?.name;}};
  if(action==='ws-download-artifact'){download(m.artifact.name,m.artifact.text);return true;}
  if(action==='ws-discard-artifact'){mutate(st=>{const message=findMessage(st);if(message)message.artifact=null;cancelPending(st,'Le brouillon a été retiré avant sa validation.');},'Brouillon retiré');return true;}
  const to=document.getElementById('artifact-to-'+ident)?.value,subject=document.getElementById('artifact-subject-'+ident)?.value,body=document.getElementById('artifact-body-'+ident)?.value;
  if(!to?.trim()||!subject?.trim()||!body?.trim()){ctx.toast('Renseignez le destinataire, l’objet et le contenu.');return true;}
  if(action==='ws-submit-artifact'&&(a.status==='paused'||c.permissions.send==='never')){ctx.toast('Le mandat ou la suspension de cet agent interdit cette demande.');return true;}
  const changed=m.artifact.to!==to||m.artifact.subject!==subject||m.artifact.text!==body;
  if(action==='ws-submit-artifact'&&!changed&&s.decisions.some(d=>d.artifactId===ident&&d.status==='pending')){ctx.toast('Ce brouillon attend déjà une validation.');return true;}
  const reviewer=s.agents.find(x=>x.type==='human'&&x.status!=='paused'&&(x.id===a.mandate?.reviewer||x.name===a.mandate?.reviewer))||s.agents.find(x=>x.type==='human'&&x.status!=='paused'&&(x.id===a.manager||x.name===a.manager));
  if(action==='ws-submit-artifact'&&(group||!reviewer)){ctx.toast('Un brouillon individuel et un responsable humain actif sont requis.');return true;}
  mutate(st=>{const artifact=findMessage(st)?.artifact;if(!artifact)return;Object.assign(artifact,{to,subject,text:body});if(changed){artifact.version=Number(artifact.version||1)+1;artifact.reviewStatus='draft';delete artifact.reviewedAt;delete artifact.reviewedBy;cancelPending(st,'Le contenu du brouillon a changé ; une nouvelle validation est requise.');}if(action==='ws-submit-artifact')st.decisions.push({id:uid('decision'),title:'Examiner le brouillon : '+subject,agentId:a.id,processId:null,artifactId:ident,type:'approval',priority:'medium',status:'pending',summary:'Simulation de communication vers '+to,assignedTo:reviewer.name,evidence:['Destinataire fictif : '+to,'Objet : '+subject,'Contenu : '+body],recommendation:'Vérifier les engagements et les destinataires.',createdAt:new Date().toISOString(),dueAt:new Date(Date.now()+86400000).toISOString(),amount:0});},action==='ws-submit-artifact'?'Brouillon soumis à validation':'Brouillon enregistré');
  ctx.toast(action==='ws-submit-artifact'?'Demande locale créée. Aucun message envoyé.':'Brouillon sauvegardé.');return true;
 }
 return false;
}
export function handleWorkspaceFile(e,ctx){if(e.target.id!=='ws-file')return;const f=e.target.files?.[0];if(!f)return;if(f.size>200000||!/\.(txt|csv|md|json)$/i.test(f.name)){ctx.toast('Choisissez un fichier .txt, .csv, .md ou .json de moins de 200 Ko.');return;}const initial=getState(),actor=initial.workspace.selectedAgentId,sessionId=initial.workspace.sessionId,owner=initial.agents.find(x=>x.id===initial.workspace.actorId)?.name;return f.text().then(text=>{const current=getState();if(current.workspace?.sessionId!==sessionId||!current.agents.some(a=>a.id===actor&&a.type==='agent')){ctx.toast('L’espace a changé pendant la lecture. Ajoutez le fichier à nouveau.');return;}update(s=>{s.workspace.knowledge.push({id:uid('doc'),name:f.name,content:text.slice(0,60000),agentIds:[actor],version:1,owner,status:'draft',updatedAt:new Date().toISOString()});s.workspace.threads[actor]||=[];s.workspace.threads[actor].push({id:uid('msg'),role:'user',text:'Document ajouté au contexte, en brouillon.',attachment:{name:f.name},time:new Date().toISOString()});},'Document local joint',f.name);ctx.toast('Document ajouté au contexte local.');}).catch(()=>ctx.toast('Le fichier n’a pas pu être lu.'));}
